$checks=0;
function axCheck(bool $ok,string $message): void {global $checks;$checks++;if(!$ok)throw new RuntimeException($message);}
function axRecord(string $month,int $step=0): array {
 $input=Settings::normalizeInput(['month'=>$month],Settings::defaults());$metrics=[];
 $labels=['Resolução no prazo','Atendimento prioritário','Resolução remota','Satisfação com chamados','Reabertura de chamados','Cumprimento de atendimento','Atendimento telefônico','Qualidade da telefonia','Abandono de ligações','Rotatividade de equipe','Capacitação da equipe','Disponibilidade da equipe'];
 for($i=1;$i<=12;$i++){$lower=in_array($i,[5,9,10],true);$value=$lower?8-$step/3:88+$step;$metrics[]=['id'=>'INS'.$i,'label'=>$labels[$i-1],'title'=>$labels[$i-1],'value'=>$value,'numerator'=>$value,'denominator'=>100,'target'=>$lower?10:90,'direction'=>$lower?'lte':'gte','status'=>$lower||$value>=90?'met':'unmet','method'=>'Valor mensal calculado no fechamento, com a população e o critério arquivados.'];}
 $snapshot=['schema_version'=>2,'rules_version'=>Settings::RULES_VERSION,'input'=>$input,'generated_at'=>str_replace(' ','T',$input['end_exclusive']).'-03:00','period'=>['month'=>$month,'start'=>$input['start'],'end_exclusive'=>$input['end_exclusive'],'date_basis'=>'solvedate','call_date_basis'=>'queue_entry'],'source_identity'=>['glpi'=>str_repeat('a',64),'callcenter'=>str_repeat('b',64)],'metrics'=>$metrics,'totals'=>['tickets'=>100+$step*10,'requests'=>70+$step,'incidents'=>30+$step,'calls_received'=>1000+$step*100,'calls_answered'=>800+$step*50,'calls_abandoned'=>100+$step,'calls_excluded'=>10+$step,'mean_talk_seconds'=>240-$step*4.125,'mean_talk_count'=>800+$step*50,'mean_wait_seconds'=>25-$step/2,'mean_wait_count'=>900+$step*60],'financial'=>['available'=>true,'complete'=>true,'gross_value'=>strval(100000+$step*500).'.01','deduction_total'=>strval(1200-$step*50).'.00','adjustment_total'=>'-0.03','net_value'=>strval(98800+$step*550).'.98','notes'=>[]]];
 $summary=MonthlySummary::fromSnapshot($snapshot);$summary['manual']=['executive_summary'=>'Acompanhamento mensal de volumes, prazos e qualidade.','actions'=>'Manter o acompanhamento dos prazos e registrar as ações no próximo fechamento.','notes'=>'=HYPERLINK("https://example.invalid","texto literal")','phone_survey_actions'=>''];$summary['staffing']=['active_count'=>12,'departures'=>0,'note'=>'Equipe registrada no fechamento.'];
 $days=[];$length=(int)(new DateTimeImmutable($month.'-01'))->format('t');for($d=1;$d<=$length;$d++)$days[]=['date'=>$month.'-'.sprintf('%02d',$d),'tickets'=>$d===1?0:($d*3+$step)%18,'calls'=>($d*17+$step*3)%120,'excluded_calls'=>$d%3];
 $series=[];foreach(['tickets','calls','excluded_calls'] as $id){$total=array_sum(array_column($days,$id));$series[$id]=['available'=>true,'total'=>$total,'observed'=>$total,'assigned'=>$total,'unassigned'=>0,'invalid_dates'=>0,'out_of_month'=>0,'future_dates'=>0,'reconciled'=>true,'status'=>'complete','date_basis'=>$id==='tickets'?'solvedate':'queue_entry'];}
 $summary['totals']['tickets']=$series['tickets']['total'];$summary['totals']['calls_received']=$series['calls']['total'];$summary['totals']['calls_excluded']=$series['excluded_calls']['total'];
 $summary['activity']=['schema_version'=>1,'revision'=>str_repeat('c',64),'month'=>$month,'status'=>'complete','period_completeness'=>'complete','generated_at'=>$snapshot['generated_at'],'timezone'=>'America/Sao_Paulo','days'=>$days,'series'=>$series,'notes'=>['Contagens por data civil na revisão arquivada.']];
 return ['id'=>'arquivo-'.$month,'month'=>$month,'archived_at'=>$snapshot['generated_at'],'summary'=>$summary];
}
function axReport(array $records,?array $months=null): array {return AnnualReport::build($records,$months??array_column($records,'month'));}
function axZip(array $report): array {$binary=(new AnnualXlsxExporter)->toBinary($report);$path=tempnam(sys_get_temp_dir(),'annual-xlsx-');file_put_contents($path,$binary);$zip=new ZipArchive;axCheck($zip->open($path)===true,'XLSX opens');$files=[];for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);$files[$name]=$zip->getFromIndex($i);if(str_ends_with($name,'.xml')||str_ends_with($name,'.rels')){$dom=new DOMDocument;axCheck($dom->loadXML($files[$name]),'Valid XML '.$name);}}$zip->close();unlink($path);return [$files,$binary];}
function axXml(string $xml): DOMXPath {$d=new DOMDocument;$d->loadXML($xml);$x=new DOMXPath($d);$x->registerNamespace('s','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$x->registerNamespace('c','http://schemas.openxmlformats.org/drawingml/2006/chart');return $x;}
function axCell(DOMXPath $x,string $ref): string {return $x->evaluate('string(//s:c[@r="'.$ref.'"]/s:v | //s:c[@r="'.$ref.'"]/s:is/s:t)');}
function axRows(DOMXPath $x,string $id): array {$result=[];foreach($x->query('//s:row[s:c[substring(@r,1,1)="B"]/s:is/s:t="'.$id.'"]') as $r)$result[]=(int)$r->getAttribute('r');return $result;}
$months=[];$records=[];for($m=1;$m<=12;$m++){$month='2025-'.sprintf('%02d',$m);$months[]=$month;if($m!==4)$records[]=axRecord($month,$m-1);}
