$records[5]['summary']['metrics']['INS4']['status']='not_applicable';$records[5]['summary']['metrics']['INS4']['value']=null;
$records[10]['summary']['period']['completeness']='provisional';$records[10]['summary']['period']['complete']=false;
$records[10]['summary']['activity']['period_completeness']='provisional';$records[10]['summary']['activity']['status']='provisional';foreach($records[10]['summary']['activity']['series'] as &$series)$series['status']='provisional';unset($series);
$records[0]['summary']['activity']['status']='partial';$records[0]['summary']['activity']['series']['excluded_calls']['status']='partial';
$records[1]['summary']['activity']['days'][1]['calls']=null;
$report=axReport($records,$months);$original=$report;[$files,$binary]=axZip($report);axCheck($report===$original,'Exporter does not mutate frozen report');
if($path=getenv('ANNUAL_XLSX_OUTPUT')){if(!is_dir(dirname($path)))mkdir(dirname($path),0777,true);file_put_contents($path,$binary);}
$workbook=axXml($files['xl/workbook.xml']);$names=[];foreach($workbook->query('//s:sheet') as $sheet)$names[]=$sheet->getAttribute('name');axCheck($names===['Painel','Tendências','Operação','Financeiro','Dados mensais','Dados diários','Notas e critérios'],'Seven analytical sheets');axCheck($workbook->query('//s:definedName[@name="_xlnm.Print_Area"]')->length===7,'Every sheet has explicit print area');
$charts=array_filter($files,fn($k)=>preg_match('~^xl/charts/chart\d+\.xml$~',$k),ARRAY_FILTER_USE_KEY);axCheck(count($charts)===20,'Twelve KPI, four operation and four readable financial panels');foreach($charts as $xml){$x=axXml($xml);axCheck($x->query('//c:lineChart')->length===1&&$x->query('//c:dateAx')->length===1,'Native monthly line chart with date axis');axCheck($x->query('//c:plotVisOnly[@val="0"]')->length===1,'Hidden source ranges still plot');axCheck(str_contains($xml,'mm/yy'),'Portuguese numeric month axis');axCheck($x->query('//c:dLbls/c:showVal[@val="1"]')->length>0,'Native value labels are enabled');axCheck($x->query('//c:legend')->length===1,'Every analytical chart has a series legend');foreach($x->query('//c:ser[not(contains(c:tx/c:v,"Meta")) and c:val/c:numRef/c:numCache/c:pt]') as $series){axCheck($x->query('c:dLbls/c:showVal[@val="1"]',$series)->length===1,'Each retained result segment has labels');axCheck($x->query('c:dLbls/c:dLbl/c:delete[@val="1"]',$series)->length===0,'No real result point is suppressed');}}
axCheck(str_contains($files['xl/charts/chart1.xml'],'val="dash"'),'Dashed frozen monthly targets');axCheck(str_contains($files['xl/charts/chart17.xml'],'Bruto')&&str_contains($files['xl/charts/chart17.xml'],'Líquido'),'Gross and net share financial chart');
$data=axXml($files['xl/worksheets/sheet5.xml']);$ins1=axRows($data,'INS1');axCheck(count($ins1)===12,'Every selected month keeps its metric source row');axCheck((float)axCell($data,'D'.$ins1[8])>1,'Values over 100 percent preserved');axCheck($data->query('//s:c[@r="J'.$ins1[1].'"]/s:f')->length===1,'Eligible adjacent metric difference is a formula');axCheck(str_contains($data->evaluate('string(//s:c[@r="J'.$ins1[1].'"]/s:f)'),'ROUND')===false,'No arbitrary rounding of exact differences');axCheck($data->query('//s:c[@r="J'.$ins1[4].'"]/s:f')->length===0,'Missing selected month breaks comparisons');$tma=axRows($data,'tma');axCheck((float)axCell($data,'J'.$tma[1])<0&&str_contains($data->evaluate('string(//s:c[@r="J'.$tma[1].'"]/s:f)'),'86400'),'Shorter duration changes are signed seconds, not negative Excel dates');axCheck($data->evaluate('string(//s:c[@r="J'.$tma[1].'"]/@s)')==='9','Signed duration deltas use signed numeric style');
$hidden=$data->query('//s:row[@hidden="1"]');axCheck($hidden->length>200,'Native chart helpers hidden from report view');$firstHidden=(int)$hidden->item(0)->getAttribute('r');$area=$workbook->evaluate('string(//s:definedName[@name="_xlnm.Print_Area" and @localSheetId="4"])');axCheck(!str_contains($area,'\\')&&(int)substr($area,strrpos($area,'$')+1)<$firstHidden,'Print area excludes helpers');
$daily=axXml($files['xl/worksheets/sheet6.xml']);axCheck($daily->query('//s:row[@r>=8]')->length===365,'Daily source stays one aggregate row per calendar date');axCheck(axCell($daily,'A8')===(string)XlsxChart::dateSerial('2025-01-01')&&axCell($daily,'C8')==='0','Exact numeric dates and true zero');axCheck($daily->query('//s:c[@r="D40"]/s:v')->length===0,'Unavailable daily count stays blank');
$op=axXml($files['xl/worksheets/sheet3.xml']);axCheck($op->query('//s:conditionalFormatting')->length===2,'Separate consistent ticket/call heatmap scales');axCheck($op->query('//s:c[@s="19"]/s:is/s:t[text()="×"]')->length>0&&$op->query('//s:c[@s="15"]/s:is/s:t[text()="—"]')->length>0,'Impossible dates and unknown observations distinct');$coverage=[];foreach($op->query('//s:c[starts-with(@r,"M")]/s:is/s:t') as $node)$coverage[]=$node->textContent;axCheck(in_array('Completo',$coverage,true),'Source-specific complete ticket coverage survives unrelated partial source');
$panel=$files['xl/worksheets/sheet1.xml'];axCheck(str_contains($panel,'N/A')&&str_contains($panel,'s="21"')&&str_contains($panel,'s="13"'),'Matrix distinguishes not applicable, pending and provisional');
$notes=$files['xl/worksheets/sheet7.xml'];axCheck(str_contains($notes,'requests:')&&str_contains($notes,'calls_answered:')&&str_contains($notes,'active_count:'),'Remaining operational/staffing frozen scalars retained');axCheck(str_contains($notes,'=HYPERLINK')&&!str_contains($notes,'<f>HYPERLINK'),'Untrusted texts are inline strings');
$short=axReport([axRecord('2026-01'),axRecord('2026-02',1)]);$long=str_repeat('á detalhe diário preservado; ',2000);$short['months'][0]['summary']['manual']['notes']=$long;[$longFiles]=axZip($short);$nx=axXml($longFiles['xl/worksheets/sheet7.xml']);$joined='';foreach($nx->query('//s:row[s:c[starts-with(@r,"B")]/s:is/s:t[starts-with(text(),"Observações")]]/s:c[starts-with(@r,"C")]/s:is/s:t') as $node){axCheck(mb_strlen($node->textContent)<32767,'Long notes fit Excel cell limits');if(str_contains($node->textContent,'detalhe diário'))$joined.=$node->textContent;}axCheck($joined===$long,'Long multibyte notes preserved over continuation rows');
$large=axReport([axRecord('2026-01'),axRecord('2026-02',1)]);$large['financial']['months'][0]['gross_cents']=9999999999999999;$large['financial']['months'][0]['adjustment_cents']=-9999999999999999;$large['financial']['subtotal_cents']['gross']=10000000010000000;$large['financial']['subtotal_cents']['adjustment']=-10000000000000002;[$lf]=axZip($large);$fx=axXml($lf['xl/worksheets/sheet4.xml']);axCheck(axCell($fx,'C9')==='R$ 99.999.999.999.999,99'&&axCell($fx,'E9')==='-R$ 99.999.999.999.999,99','Huge signed amounts keep exact cents as text');axCheck($fx->query('//s:c[@r="C11"]/s:f')->length===0&&str_contains(axCell($fx,'C11'),'100.000.000.100.000,00'),'Affected subtotal is exact text without misleading SUMIF');
$cancel=axReport([axRecord('2026-01'),axRecord('2026-02',1)]);$cancel['financial']['months'][0]['adjustment_cents']=999999999999999;$cancel['financial']['months'][1]['adjustment_cents']=-999999999999998;$cancel['financial']['subtotal_cents']['adjustment']=1;[$cf]=axZip($cancel);$cx=axXml($cf['xl/worksheets/sheet4.xml']);axCheck(axCell($cx,'E11')==='R$ 0,01'&&$cx->query('//s:c[@r="E11"]/s:f')->length===0,'Large intermediate cancellation retains exact small subtotal');axCheck($cx->query('//s:c[@r="F11"]/s:f')->length===1,'Ordinary money remains functional SUMIF');
[$empty]=axZip(axReport([],['2026-01']));$ex=axXml($empty['xl/worksheets/sheet4.xml']);axCheck(axCell($ex,'F10')===''&&str_contains($ex->evaluate('string(//s:c[@r="F10"]/s:f)'),'COUNTIF'),'No complete financial month remains blank after recalc');
$gap=axReport([axRecord('2026-01'),axRecord('2026-03',3)]);[$gf]=axZip($gap);$gx=axXml($gf['xl/worksheets/sheet5.xml']);axCheck((float)axCell($gx,'J9')===3.0&&str_contains(axCell($gx,'L9'),'Não é uma variação mensal')&&str_contains(axCell($gx,'L9'),'2026-01'),'Legitimate selected-interval comparison survives in audit data with interval label');$gc=axXml($gf['xl/charts/chart1.xml']);axCheck($gc->query('//c:ser/c:spPr/*[local-name()="ln"]/*[local-name()="noFill"]')->length>0,'Selected-interval delta never reconnects monthly trend');
// Values, identities and panel boundaries remain readable for all supported selection lengths.
foreach([1,6,12,13,24] as $count){
 $rr=[];for($i=0;$i<$count;$i++)$rr[]=axRecord((new DateTimeImmutable('2024-01-01'))->modify('+'.$i.' months')->format('Y-m'),$i);
 $rr[0]['summary']['metrics']['INS1']['value']=99.50;
 foreach($rr[0]['summary']['activity']['days'] as &$day)$day['tickets']=0;unset($day);$rr[0]['summary']['activity']['days'][1]['tickets']=100000;
 $dailyTotal=array_sum(array_column($rr[0]['summary']['activity']['days'],'tickets'));
 foreach(['total','observed','assigned'] as $field)$rr[0]['summary']['activity']['series']['tickets'][$field]=$dailyTotal;
 $rr[0]['summary']['totals']['tickets']=$dailyTotal;
 [$pf,$pb]=axZip(axReport($rr));$pc=array_filter($pf,fn($name)=>preg_match('~^xl/charts/chart\d+\.xml$~',$name),ARRAY_FILTER_USE_KEY);
 axCheck(count($pc)===16*(int)ceil($count/12)+2*(int)ceil($count/6),'Bounded full-width panels for '.$count.' months');
 foreach($pc as $chart){$cx=axXml($chart);axCheck((int)$cx->evaluate('string(//c:ser[1]/c:cat/c:numRef/c:numCache/c:ptCount/@val)')<=12,'No panel has more than twelve selected months');}
 $firstChart=axXml($pf['xl/charts/chart1.xml']);axCheck($firstChart->evaluate('string(//c:ser[1]/c:dLbls/c:numFmt/@formatCode)')==='0.00%','99.50 percent uses two decimal places in labels');
 axCheck($firstChart->evaluate('string(//c:valAx/c:numFmt/@formatCode)')==='0%','Axis format is independent of label precision');
 $opx=axXml($pf['xl/worksheets/sheet3.xml']);$largeCells=$opx->query('//s:c[@s="20" and s:v="100000"]');axCheck($largeCells->length===1,'Six-digit positive daily count remains a numeric cell');axCheck($opx->query('//s:conditionalFormatting[contains(@sqref," ")]')->length===2,'One source-wide scale spans all day blocks');
 axCheck(str_contains($pf['xl/worksheets/sheet3.xml'],'Soma + sem data')&&str_contains($pf['xl/worksheets/sheet3.xml'],'Confere'),'Heatmaps include numeric reconciliation');
 if($count>12){$p1=axXml($pf['xl/charts/chart1.xml']);$p2=axXml($pf['xl/charts/chart2.xml']);foreach(['min','max'] as $bound)axCheck($p1->evaluate('string(//c:valAx/c:scaling/c:'.$bound.'/@val)')===$p2->evaluate('string(//c:valAx/c:scaling/c:'.$bound.'/@val)'),'Panels share '.$bound.' scale');}
 if($qa=getenv('ANNUAL_XLSX_QA_DIR')){if(!is_dir($qa))mkdir($qa,0777,true);file_put_contents($qa.'/annual_'.$count.'.xlsx',$pb);}
